// Pendulum parameters
const gravity = 9.81; // m/s^2
const pendulumLength = 100; // pixels
const pendulumMass = 1; // kg
const initialAngle = 45; // degrees
const damping = 0.9; // coefficient of drag

// Get the canvas and context
const canvas = document.getElementById('pendulumCanvas');
const ctx = canvas.getContext('2d');

// Set the canvas dimensions
canvas.width = 400;
canvas.height = 400;

// Initialize the pendulum state
let theta = Math.radians(initialAngle);
let omega = 0;
let angularVelocity = 0;

// Main simulation loop
function simulate() {
  // Update the pendulum state
  angularVelocity += (-gravity / pendulumLength) * Math.sin(theta);
  theta += omega;
  omega = angularVelocity * (1 - damping);

  // Check for collision with the bottom of the screen
  if (theta > Math.PI / 2) {
    theta = Math.PI / 2;
    angularVelocity = 0;
  }

  // Clear the canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw the pendulum
  ctx.save();
  ctx.translate(canvas.width / 2, canvas.height / 2);
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(0, pendulumLength * Math.sin(theta));
  ctx.stroke();
  ctx.restore();

  // Request the next frame
  requestAnimationFrame(simulate);
}

// Start the simulation
function startSimulation() {
  simulate();
}

// Stop the simulation
function stopSimulation() {
  cancelAnimationFrame(simulate);
}

// Event listener for the button
document.getElementById('releaseButton').addEventListener('click', () => {
  startSimulation();
});
